import { expect, jest, test } from '@jest/globals';
import loadHeadlessAbilities from '../abilities/Headless';
import { Ability } from '../ability';
import { Creature } from '../creature';
import { unitData } from '../data/units';

jest.mock('phaser', () =>
	(
		jest.requireActual('../../test/phaser-mock') as typeof import('../../test/phaser-mock')
	).createPhaserMock(),
);
jest.mock('../game-display/camera', () => ({ shakeBoard: jest.fn() }));
// The asset manifest is generated by the app build; this fixture creates no sprites.
jest.mock('../assets', () => ({}));

test('an unupgraded Boomerang Tool sweep damages both the upper Bounty Hunter and lower multihex Stomper', () => {
	const game: any = {
		abilities: [],
		// Use the native replay fast-forward path to finish projectile encounters
		// synchronously, without replacing the ability or projectile hit logic.
		replayMode: 'load',
		grid: {
			hexes: Array.from({ length: 9 }, (_, y) =>
				Array.from({ length: y % 2 === 0 ? 15 : 16 }, (_, x) => ({
					x,
					y,
					creature: undefined as Creature | undefined,
				})),
			),
			queryChoice: jest.fn(),
		},
		UI: { updateFatigue: jest.fn(), checkAbilities: jest.fn() },
		animations: { tiltBackward: jest.fn() },
		onUnderAttack: jest.fn(),
		onAttack: jest.fn(),
		onDamage: jest.fn(),
		log: jest.fn(),
	};

	function placeCreature(name: string, id: number, x: number, y: number, team: number): Creature {
		const data = unitData.find((unit) => unit.name === name);
		if (!data) {
			throw new Error(`Missing playable unit: ${name}`);
		}
		// Bypass sprite construction, but retain Creature identity and its actual
		// takeDamage, fatigue and status logic. Stats come from the playable unit.
		const creature: Creature = Object.assign(Object.create(Creature.prototype), {
			game,
			id,
			name,
			x,
			y,
			team,
			size: data.size,
			player: { flipped: team === 1, score: [] },
			stats: { ...data.vitals, ...data.masteries },
			health: data.vitals.health,
			endurance: data.vitals.endurance,
			dead: false,
			status: { frozen: false, cryostasis: false, dizzy: false },
			abilities: [],
			effects: [],
			// None of the three units are adjacent in the reported encounter.
			adjacentHexes: () => [],
			hint: jest.fn(),
			updateHealth: jest.fn(),
			queryMove: jest.fn(),
		});
		creature.hexagons = Array.from({ length: creature.size }, (_, offset) => {
			const hex = game.grid.hexes[y][x - offset];
			hex.creature = creature;
			return hex;
		});
		return creature;
	}

	// Positions and initial health match the selected pre-attack encounter.
	const headless = placeCreature('Headless', 2, 5, 4, 0);
	const bountyHunter = placeCreature('Bounty Hunter', 3, 8, 3, 1);
	const stomper = placeCreature('Stomper', 4, 10, 5, 1);
	game.activeCreature = headless;
	loadHeadlessAbilities(game);
	const boomerang: any = Object.assign(
		Object.create(Ability.prototype),
		game.abilities[39][3],
		unitData.find((unit) => unit.name === 'Headless')?.ability_info[3],
		{
			game,
			creature: headless,
			isUpgraded: () => false,
			end: jest.fn(),
		},
	);
	// Skip only the generic cast animation when the targeting query confirms.
	boomerang.animation = (hexes: any[]) => boomerang.activate(hexes);
	const stomperDamage = jest.spyOn(stomper, 'takeDamage');

	expect(bountyHunter.health).toBe(100);
	expect(stomper.health).toBe(135);
	boomerang.query();
	const query: any = game.grid.queryChoice.mock.calls[0][0];
	// The reported click is an empty upper-row hex to the right of Headless.
	const clickedHex = game.grid.hexes[3][7];
	expect(clickedHex.creature).toBeUndefined();
	const sweep = query.choices.find((choice: any[]) => choice.includes(clickedHex));
	expect(sweep).toBeDefined();
	expect(sweep).toEqual(expect.arrayContaining([bountyHunter.hexagons[0], ...stomper.hexagons]));
	for (const hex of [bountyHunter.hexagons[0], ...stomper.hexagons]) {
		expect(query.hexesDeadZone).not.toContain(hex);
	}
	query.fnOnConfirm(sweep);

	// Control: the throw completed and reproduced the observed upper-row hit.
	expect(headless.queryMove).toHaveBeenCalledTimes(1);
	expect(bountyHunter.health).toBe(90);
	// Both occupied Stomper hexes are damaging, not a reason to skip the enemy.
	expect(stomper.health).toBeLessThan(135);
	expect(stomperDamage).toHaveBeenCalledTimes(1);
});
